/**
 * Measurements of the 32 teeth in `src/assets/teeth/teeth.glb`.
 *
 * GENERATED by `tools/extract-teeth-3d.py` from
 * `teeth_skeleton_ligaments.blend`. Do not edit by hand — re-run the
 * script instead. See its docstring for how the meshes are oriented.
 *
 * Unlike the rest of `src/data/`, this is not placeholder content: the
 * figures are measured off the real geometry the chart draws.
 */

import type { Arch, ToothType } from './patientChart.ts'

export interface ToothModel {
  /** FDI two-digit notation, matching `Tooth.fdi`. */
  fdi: number
  /** Name of this tooth's node inside `teeth.glb`. */
  node: string
  arch: Arch
  type: ToothType
  /** Millimetres: mesiodistal, occlusogingival, buccolingual. */
  size: { width: number; height: number; depth: number }
  /**
   * Where the tooth stood in the skull — metres, glTF axes. The GLB
   * ships every tooth squared up at the origin instead, so an
   * anatomical view sets these two on the node to put it back. They
   * are the export's transform inverted, so applying both restores
   * the real arch exactly.
   */
  archPosition: [number, number, number]
  archRotation: [number, number, number, number]
}

/**
 * The set's largest tooth on each axis, millimetres. A chart row scales
 * itself so this fits, which keeps every tooth in the row at ONE shared
 * scale — the whole point of using the real meshes, since it is what
 * makes a molar read as bigger than an incisor.
 */
export const TOOTH_EXTENT = { width: 12.76, height: 30.29, depth: 11.01 }

/**
 * The whole dentition's extent once every tooth is back in its
 * `archPosition` — metres, glTF axes, roots included.
 *
 * The blend measures from the figure's feet, so this sits about 1.67 m
 * up. An arch view offsets by the centre of this box to bring the teeth
 * to the origin where they can be orbited, and sizes its camera from the
 * box's dimensions rather than a distance somebody guessed.
 */
export const ARCH_BOUNDS = {
  min: [-0.03352, 1.63716, -0.55974] as [number, number, number],
  max: [0.03459, 1.69291, -0.50019] as [number, number, number],
}

